import{_ as e,o as a,c as d,a2 as r}from"./chunks/framework.il0noOp3.js";const m=JSON.parse('{"title":"AI Readiness -- enumerated source for the Microsoft AI Readiness Assessment","description":"","frontmatter":{},"headers":[],"relativePath":"frameworks/ai-readiness-question-set.md","filePath":"frameworks/ai-readiness-question-set.md"}'),s={name:"frameworks/ai-readiness-question-set.md"};function o(n,t,i,c,l,u){return a(),d("div",null,[...t[0]||(t[0]=[r('<h1 id="ai-readiness-enumerated-source-for-the-microsoft-ai-readiness-assessment" tabindex="-1">AI Readiness -- enumerated source for the Microsoft AI Readiness Assessment <a class="header-anchor" href="#ai-readiness-enumerated-source-for-the-microsoft-ai-readiness-assessment" aria-label="Permalink to &quot;AI Readiness -- enumerated source for the Microsoft AI Readiness Assessment&quot;">​</a></h1><p><strong>Enumerated 2026-11-25. Verification method and limits are stated below -- read them before quoting any coverage number from this page.</strong></p><p>Scout&#39;s <code>ai.readiness.yaml</code> scores the review in Microsoft&#39;s <a href="https://learn.microsoft.com/en-us/assessments/94f1c697-9ba7-4d47-ad83-7c6bd94b1505/" target="_blank" rel="noreferrer">AI Readiness Assessment</a>, an enterprise-level assessment of organisational preparedness across seven pillars: Business Strategy, AI Governance &amp; Security, Data Foundations, AI Strategy &amp; Experience, Organization &amp; Culture, Infrastructure for AI and Model Management. <code>src/assess/rules/ai.readiness.yaml</code> is written against this page only, and every rule cites an item number from the tables below. Most items are organisational, so they are <strong>manual</strong> questions answered with <code>-AssessmentAnswers</code>; the infrastructure, governance and data items that Azure data can answer are <strong>automated</strong>.</p><h2 id="source" tabindex="-1">Source <a class="header-anchor" href="#source" aria-label="Permalink to &quot;Source&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Value</th></tr></thead><tbody><tr><td>Assessment</td><td><a href="https://learn.microsoft.com/en-us/assessments/94f1c697-9ba7-4d47-ad83-7c6bd94b1505/" target="_blank" rel="noreferrer">AI Readiness Assessment</a> (seven pillars; question text not published)</td></tr><tr><td>Framework version</td><td>Cloud Adoption Framework AI adoption and AI agent adoption guidance on Microsoft Learn, current as of the extraction date (no published version number)</td></tr><tr><td>Extraction date</td><td>2026-11-25</td></tr><tr><td>Verification method</td><td>The seven pillar names come from the assessment&#39;s own description. Each source page below was fetched with the Microsoft Learn MCP tools (<code>microsoft_docs_fetch</code>, <code>microsoft_docs_search</code>) on 2026-11-25. Every property an automated item reads was checked against the collect.json contract in <code>src/collect/Invoke-Collect.ps1</code>.</td></tr></tbody></table><h2 id="the-one-thing-this-enumeration-is-not" tabindex="-1">The one thing this enumeration is NOT <a class="header-anchor" href="#the-one-thing-this-enumeration-is-not" aria-label="Permalink to &quot;The one thing this enumeration is NOT&quot;">​</a></h2><p><strong>It is not Microsoft&#39;s question list.</strong> The assessment&#39;s questions and scoring are not published, so the items below are <strong>Scout-derived</strong>: Scout&#39;s reading of the CAF AI adoption pages (strategy, plan, ready, govern, secure, manage) and the CAF AI agent adoption pages, grouped under the seven pillar names the assessment uses. The <code>AIRDY-*</code> IDs are Scout&#39;s own, and the assignment of an item to a pillar is Scout&#39;s judgement. Microsoft reports readiness as a stage (Exploring, Planning, Implementing, Scaling, Realizing); Scout reports a percentage per pillar and does not map it to those stages.</p><p>Sources:</p><ul><li>[STR] <a href="https://learn.microsoft.com/azure/cloud-adoption-framework/ai/strategy" target="_blank" rel="noreferrer">AI adoption (CAF AI strategy)</a></li><li>[PLN] <a href="https://learn.microsoft.com/azure/cloud-adoption-framework/ai/plan" target="_blank" rel="noreferrer">Plan for AI adoption</a></li><li>[RDY] <a href="https://learn.microsoft.com/azure/cloud-adoption-framework/ai/ready" target="_blank" rel="noreferrer">Architecture and governance for AI (AI ready)</a></li><li>[GOVP] <a href="https://learn.microsoft.com/azure/cloud-adoption-framework/ai/platform/governance" target="_blank" rel="noreferrer">Govern Azure platform services (PaaS) for AI</a></li><li>[SECP] <a href="https://learn.microsoft.com/azure/cloud-adoption-framework/ai/platform/security" target="_blank" rel="noreferrer">Secure Azure platform services (PaaS) for AI</a></li><li>[SEC] <a href="https://learn.microsoft.com/azure/cloud-adoption-framework/ai/secure" target="_blank" rel="noreferrer">Guidance to set up your organization&#39;s AI security process</a></li><li>[RAIP] <a href="https://learn.microsoft.com/azure/cloud-adoption-framework/ai/responsible-ai-policies" target="_blank" rel="noreferrer">Responsible AI policies</a></li><li>[AGS] <a href="https://learn.microsoft.com/azure/cloud-adoption-framework/ai-agents/" target="_blank" rel="noreferrer">AI agent adoption strategy</a></li><li>[AGO] <a href="https://learn.microsoft.com/azure/cloud-adoption-framework/ai-agents/organizational-readiness" target="_blank" rel="noreferrer">Organizational readiness for AI agents</a></li><li>[AMM] <a href="https://learn.microsoft.com/agents/adoption-maturity-model/" target="_blank" rel="noreferrer">Agentic AI adoption maturity model</a></li><li>[MLO] <a href="https://learn.microsoft.com/azure/well-architected/ai/mlops-genaiops" target="_blank" rel="noreferrer">MLOps and GenAIOps for AI workloads on Azure</a></li><li>[OPS] <a href="https://learn.microsoft.com/azure/well-architected/ai/operations" target="_blank" rel="noreferrer">AI workload operations on Azure</a></li></ul><p>Automated items are <strong>gated</strong>: they run only when the resources they judge exist, so an estate without them reports those items Not assessed rather than passed or failed. Manual items are answered with <code>-AssessmentAnswers</code> (see <a href="./../assessment/questionnaire-answers.html">Questionnaire Answers</a>); where collected Azure data bears on the question it is attached to the item as evidence.</p><h2 id="the-enumeration-64-items-across-7-pillars" tabindex="-1">The enumeration -- 64 items across 7 pillars <a class="header-anchor" href="#the-enumeration-64-items-across-7-pillars" aria-label="Permalink to &quot;The enumeration -- 64 items across 7 pillars&quot;">​</a></h2><h3 id="business-strategy-bs-8-items" tabindex="-1">Business strategy (BS) -- 8 items <a class="header-anchor" href="#business-strategy-bs-8-items" aria-label="Permalink to &quot;Business strategy (BS) -- 8 items&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Scout</th><th>Source</th></tr></thead><tbody><tr><td>AIRDY-BS-01</td><td>The business outcomes AI is expected to support are defined</td><td>Manual</td><td>STR</td></tr><tr><td>AIRDY-BS-02</td><td>Use cases are prioritised jointly by business and IT on outcomes, not novelty</td><td>Manual</td><td>PLN, AGO</td></tr><tr><td>AIRDY-BS-03</td><td>Success measures are defined before deployment and value is tracked</td><td>Manual</td><td>PLN, AMM</td></tr><tr><td>AIRDY-BS-04</td><td>Each use case is matched to the right technique (automation, RAG or agent)</td><td>Manual</td><td>AGS</td></tr><tr><td>AIRDY-BS-05</td><td>Buy, build or customise is decided against the Microsoft AI decision tree</td><td>Manual -- <code>domains.ai.cognitiveAccounts</code> attached as evidence</td><td>STR</td></tr><tr><td>AIRDY-BS-06</td><td>Executives sponsor AI visibly and set a common direction</td><td>Manual</td><td>STR</td></tr><tr><td>AIRDY-BS-07</td><td>AI spend is budgeted and managed</td><td>Manual -- <code>governance.budgets</code> attached as evidence</td><td>PLN, AGO</td></tr><tr><td>AIRDY-BS-08</td><td>Business processes are redesigned for human and AI collaboration</td><td>Manual</td><td>AMM</td></tr></tbody></table><h3 id="ai-governance-and-security-gs-12-items" tabindex="-1">AI governance and security (GS) -- 12 items <a class="header-anchor" href="#ai-governance-and-security-gs-12-items" aria-label="Permalink to &quot;AI governance and security (GS) -- 12 items&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Scout</th><th>Source</th></tr></thead><tbody><tr><td>AIRDY-GS-01</td><td>AI governance is owned centrally with Responsible AI policies</td><td>Manual</td><td>STR, RAIP</td></tr><tr><td>AIRDY-GS-02</td><td>AI use cases pass a Responsible AI review before release</td><td>Manual</td><td>PLN, RAIP</td></tr><tr><td>AIRDY-GS-03</td><td>A complete inventory of AI assets is kept</td><td>Manual -- <code>domains.ai.cognitiveAccounts</code> attached as evidence</td><td>SEC</td></tr><tr><td>AIRDY-GS-04</td><td>Azure Policy assignments govern AI deployments</td><td>Automated -- <code>governance.policyAssignments</code></td><td>GOVP</td></tr><tr><td>AIRDY-GS-05</td><td>Azure AI accounts have a managed identity</td><td>Automated -- <code>domains.ai.cognitiveAccounts</code></td><td>GOVP, SECP</td></tr><tr><td>AIRDY-GS-06</td><td>Azure AI accounts do not accept API keys</td><td>Automated -- <code>domains.ai.cognitiveAccounts</code></td><td>SECP</td></tr><tr><td>AIRDY-GS-07</td><td>Azure AI accounts have public network access disabled</td><td>Automated -- <code>domains.ai.cognitiveAccounts</code></td><td>GOVP</td></tr><tr><td>AIRDY-GS-08</td><td>Defender for Cloud threat protection for AI services is enabled</td><td>Automated -- <code>security.defenderPlans</code></td><td>GOVP, SEC</td></tr><tr><td>AIRDY-GS-09</td><td>Sensitive data is classified and labelled before AI uses it</td><td>Manual -- <code>domains.analytics.purviewAccounts</code> attached as evidence</td><td>SECP, SEC</td></tr><tr><td>AIRDY-GS-10</td><td>Access to AI resources is least privilege, with just-in-time administration</td><td>Manual</td><td>GOVP</td></tr><tr><td>AIRDY-GS-11</td><td>AI agents have their own governed identities and limited tool permissions</td><td>Manual</td><td>SECP, AGS</td></tr><tr><td>AIRDY-GS-12</td><td>Regulatory, residency and compliance requirements for AI are mapped</td><td>Manual -- <code>domains.ai.cognitiveAccounts</code> attached as evidence</td><td>PLN, GOVP</td></tr></tbody></table><h3 id="data-foundations-df-8-items" tabindex="-1">Data foundations (DF) -- 8 items <a class="header-anchor" href="#data-foundations-df-8-items" aria-label="Permalink to &quot;Data foundations (DF) -- 8 items&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Scout</th><th>Source</th></tr></thead><tbody><tr><td>AIRDY-DF-01</td><td>The data each AI capability needs is identified</td><td>Manual</td><td>STR</td></tr><tr><td>AIRDY-DF-02</td><td>A data catalogue governs the data estate</td><td>Automated -- <code>domains.analytics.purviewAccounts</code></td><td>STR, SEC</td></tr><tr><td>AIRDY-DF-03</td><td>Data quality standards are defined and measured</td><td>Manual -- <code>domains.analytics.dataFactories</code> attached as evidence</td><td>STR</td></tr><tr><td>AIRDY-DF-04</td><td>A unified data platform serves AI and analytics</td><td>Manual -- <code>domains.analytics.fabricCapacities</code> attached as evidence</td><td>STR</td></tr><tr><td>AIRDY-DF-05</td><td>Data lineage and provenance can be shown</td><td>Manual</td><td>MLO</td></tr><tr><td>AIRDY-DF-06</td><td>Data boundaries are defined for each AI workload</td><td>Manual</td><td>SECP</td></tr><tr><td>AIRDY-DF-07</td><td>Data factories do not accept public network access</td><td>Automated -- <code>domains.analytics.dataFactories</code></td><td>SECP</td></tr><tr><td>AIRDY-DF-08</td><td>Grounding data and search indexes are kept fresh</td><td>Manual -- <code>domains.ai.searchServices</code> attached as evidence</td><td>MLO</td></tr></tbody></table><h3 id="ai-strategy-and-experience-sx-8-items" tabindex="-1">AI strategy and experience (SX) -- 8 items <a class="header-anchor" href="#ai-strategy-and-experience-sx-8-items" aria-label="Permalink to &quot;AI strategy and experience (SX) -- 8 items&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Scout</th><th>Source</th></tr></thead><tbody><tr><td>AIRDY-SX-01</td><td>AI experiences are designed around user goals</td><td>Manual</td><td>AMM</td></tr><tr><td>AIRDY-SX-02</td><td>Hand-offs between AI and people are clear</td><td>Manual</td><td>AMM</td></tr><tr><td>AIRDY-SX-03</td><td>User feedback improves AI experiences</td><td>Manual</td><td>AMM, MLO</td></tr><tr><td>AIRDY-SX-04</td><td>AI experiences are consistent across solutions</td><td>Manual</td><td>AMM</td></tr><tr><td>AIRDY-SX-05</td><td>The set of approved AI solutions is defined and available</td><td>Manual</td><td>STR, AGS</td></tr><tr><td>AIRDY-SX-06</td><td>Employees have access to approved AI together with training</td><td>Manual</td><td>STR</td></tr><tr><td>AIRDY-SX-07</td><td>The AI strategy is revisited as telemetry and maturity grow</td><td>Manual</td><td>AMM</td></tr><tr><td>AIRDY-SX-08</td><td>Responsible AI is part of the strategy and builds trust</td><td>Manual</td><td>AMM, RAIP</td></tr></tbody></table><h3 id="organization-and-culture-oc-8-items" tabindex="-1">Organization and culture (OC) -- 8 items <a class="header-anchor" href="#organization-and-culture-oc-8-items" aria-label="Permalink to &quot;Organization and culture (OC) -- 8 items&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Scout</th><th>Source</th></tr></thead><tbody><tr><td>AIRDY-OC-01</td><td>Roles and ownership for AI are defined</td><td>Manual</td><td>AGO</td></tr><tr><td>AIRDY-OC-02</td><td>AI skills are assessed and a training plan exists</td><td>Manual</td><td>AGO, PLN</td></tr><tr><td>AIRDY-OC-03</td><td>A cross-functional team or Center of Excellence supports AI adoption</td><td>Manual</td><td>STR, AGO</td></tr><tr><td>AIRDY-OC-04</td><td>Change management prepares people for new roles and processes</td><td>Manual</td><td>AGO</td></tr><tr><td>AIRDY-OC-05</td><td>Culture and incentives encourage responsible experimentation</td><td>Manual</td><td>AMM</td></tr><tr><td>AIRDY-OC-06</td><td>A community of practice shares AI lessons</td><td>Manual</td><td>AMM</td></tr><tr><td>AIRDY-OC-07</td><td>Employees can raise concerns about AI use</td><td>Manual</td><td>RAIP</td></tr><tr><td>AIRDY-OC-08</td><td>Financial management for AI is in place</td><td>Manual</td><td>AGO</td></tr></tbody></table><h3 id="infrastructure-for-ai-in-10-items" tabindex="-1">Infrastructure for AI (IN) -- 10 items <a class="header-anchor" href="#infrastructure-for-ai-in-10-items" aria-label="Permalink to &quot;Infrastructure for AI (IN) -- 10 items&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Scout</th><th>Source</th></tr></thead><tbody><tr><td>AIRDY-IN-01</td><td>AI workloads use the existing Azure landing zone architecture</td><td>Manual -- <code>governance.managementGroups</code> attached as evidence</td><td>RDY</td></tr><tr><td>AIRDY-IN-02</td><td>The platform chosen carries the least operational responsibility that meets the need</td><td>Manual -- <code>domains.ai.mlWorkspaces</code> attached as evidence</td><td>STR</td></tr><tr><td>AIRDY-IN-03</td><td>Model quotas and capacity are planned</td><td>Manual</td><td>GOVP</td></tr><tr><td>AIRDY-IN-04</td><td>Azure AI accounts have a private endpoint</td><td>Automated -- <code>domains.ai.cognitiveAccounts</code></td><td>GOVP, SECP</td></tr><tr><td>AIRDY-IN-05</td><td>Machine learning workspaces have public network access disabled</td><td>Automated -- <code>domains.ai.mlWorkspaces</code></td><td>GOVP</td></tr><tr><td>AIRDY-IN-06</td><td>Machine learning workspaces use managed network isolation</td><td>Automated -- <code>domains.ai.mlWorkspaces</code></td><td>GOVP</td></tr><tr><td>AIRDY-IN-07</td><td>AI Search services have public network access disabled</td><td>Automated -- <code>domains.ai.searchServices</code></td><td>GOVP</td></tr><tr><td>AIRDY-IN-08</td><td>AI workloads are monitored and alerted on</td><td>Manual -- <code>opsPosture.diagnosticCoverage</code> attached as evidence</td><td>OPS, GOVP</td></tr><tr><td>AIRDY-IN-09</td><td>Business continuity covers AI model endpoints</td><td>Manual</td><td>GOVP</td></tr><tr><td>AIRDY-IN-10</td><td>Infrastructure for custom models is justified and right-sized</td><td>Manual</td><td>STR</td></tr></tbody></table><h3 id="model-management-mm-10-items" tabindex="-1">Model management (MM) -- 10 items <a class="header-anchor" href="#model-management-mm-10-items" aria-label="Permalink to &quot;Model management (MM) -- 10 items&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Scout</th><th>Source</th></tr></thead><tbody><tr><td>AIRDY-MM-01</td><td>A list of approved models is maintained</td><td>Manual</td><td>GOVP, MLO</td></tr><tr><td>AIRDY-MM-02</td><td>Model selection weighs fit, cost and risk</td><td>Manual</td><td>GOVP, MLO</td></tr><tr><td>AIRDY-MM-03</td><td>Model versions are pinned and retirement dates are tracked</td><td>Manual</td><td>GOVP</td></tr><tr><td>AIRDY-MM-04</td><td>Models are evaluated before production</td><td>Manual</td><td>MLO</td></tr><tr><td>AIRDY-MM-05</td><td>Prompt and model changes are managed with rollback</td><td>Manual</td><td>GOVP, MLO</td></tr><tr><td>AIRDY-MM-06</td><td>Model drift and decay are monitored</td><td>Manual</td><td>MLO, OPS</td></tr><tr><td>AIRDY-MM-07</td><td>A workspace or registry tracks custom models and experiments</td><td>Manual -- <code>domains.ai.mlWorkspaces</code> attached as evidence</td><td>MLO</td></tr><tr><td>AIRDY-MM-08</td><td>Fine-tuning is governed</td><td>Manual</td><td>MLO</td></tr><tr><td>AIRDY-MM-09</td><td>Content safety guardrails are bound to every model deployment</td><td>Manual</td><td>MLO, OPS</td></tr><tr><td>AIRDY-MM-10</td><td>MLOps and GenAIOps practices operate the model lifecycle</td><td>Manual</td><td>MLO</td></tr></tbody></table><h2 id="summary" tabindex="-1">Summary <a class="header-anchor" href="#summary" aria-label="Permalink to &quot;Summary&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Area</th><th>Items</th><th>Automated</th><th>Manual</th></tr></thead><tbody><tr><td>Business strategy</td><td>8</td><td>0</td><td>8</td></tr><tr><td>AI governance and security</td><td>12</td><td>5</td><td>7</td></tr><tr><td>Data foundations</td><td>8</td><td>2</td><td>6</td></tr><tr><td>AI strategy and experience</td><td>8</td><td>0</td><td>8</td></tr><tr><td>Organization and culture</td><td>8</td><td>0</td><td>8</td></tr><tr><td>Infrastructure for AI</td><td>10</td><td>4</td><td>6</td></tr><tr><td>Model management</td><td>10</td><td>0</td><td>10</td></tr><tr><td><strong>Total</strong></td><td><strong>64</strong></td><td><strong>11</strong></td><td><strong>53</strong></td></tr></tbody></table><p>An estate with no AI resources reports the automated items Not assessed, so its score rests on the answers to the manual items. That is deliberate: &quot;no AI resources yet&quot; is a fact about the estate, not a pass.</p>',28)])])}const A=e(s,[["render",o]]);export{m as __pageData,A as default};
